 /* Builds center-out column ordering: e.g., for cols=7 -> [3, 2, 4, 1, 5, 0, 6] */
 static void build_center_out_order(int cols, int order[MAX_DIM]) {
     int mid = cols / 2;
     int idx = 0;
     order[idx++] = mid;

     for (int offset = 1; idx < cols; offset++) {
         int left = mid - offset;
         int right = mid + offset;
         if (left >= 0) {
             order[idx++] = left;
         }
         if (right < cols && idx < cols) {
             order[idx++] = right;
         }
     }
 }

