                int rr=r+k*dr[d], cc=c+k*dc[d];
                if(rr<0||rr>=s->rows||cc<0||cc>=s->cols||s->board[rr][cc]!=p){ok=0;break;}
            }
            if(ok){if(p==1)p1=1;else p2=1;}
        }
    }
    if(p1&&p2)return 3; if(p1)return 1; if(p2)return 2; return 0;
}

static AIGameState random_legal_state(int rows,int cols,int k){
    AIGameState s={0}; s.rows=rows;s.cols=cols;s.win_length=k;s.current_player=1;
    while(1){
        int c=(int)(rnd()%cols), placed=0;
        for(int r=0;r<rows;r++) if(s.board[r][c]==0){s.board[r][c]=(uint8_t)s.current_player;s.move_count++;s.current_player=(s.current_player==1)?2:1;placed=1;break;}
        if(!placed) continue;
        if((int)(rnd()%100)<18 || s.move_count>=rows*cols || oracle_winner(&s)!=0) break;
    }
    return s;
}

static int oracle_apply(const AIGameState *s, int col, AIGameState *out){
    if(!s||col<0||col>=s->cols||out==NULL)return 0;
    *out=*s;
    for(int r=0;r<s->rows;r++) if(out->board[r][col]==0){out->board[r][col]=(uint8_t)s->current_player;out->move_count++;out->current_player=(s->current_player==1)?2:1;return 1;}
    return 0;
}

static int oracle_minimax(const AIGameState *s,int depth){
    int w=oracle_winner(s);
    if(w==3)return 0;
    if(w!=0)return (w==s->current_player)?(1000000+depth):(-1000000-depth);
    if(depth<=0)return evaluate_board(s);
    int best=-20000000;
    for(int c=0;c<s->cols;c++){
        AIGameState n; if(!oracle_apply(s,c,&n))continue;
        int v=-oracle_minimax(&n,depth-1);
        if(v>best)best=v;
    }
    return best==-20000000?0:best;
}

