static bool valid_state(const AIGameState *s) {
    if (!s || s->rows < 1 || s->rows > MAX_DIM ||
        s->cols < 1 || s->cols > MAX_DIM ||
        s->win_length < 4 || s->win_length > MAX_DIM ||
        (s->win_length > s->rows && s->win_length > s->cols) ||
