        s->move_count < 0 || s->move_count > s->rows * s->cols) {
        return false;
    }

    int piece_count = 0;
    int p1_count = 0;
    int p2_count = 0;
    for (int c = 0; c < s->cols; c++) {
        bool seen_empty = false;
        for (int r = 0; r < s->rows; r++) {
            uint8_t cell = s->board[r][c];
            if (cell > 2) {
                return false;
            }
            if (cell == 0) {
                seen_empty = true;
            } else {
                if (seen_empty) {
                    return false;
                }
                piece_count++;
                if (cell == 1) {
                    p1_count++;
                } else {
                    p2_count++;
                }
            }
        }
